argv:
$ErrorActionPreference='Stop'
$dst='E:\boss-R67-QA-VERIFY-20261014-GPT6'
$sha='b88a80f930add09de9de6d4d7d1866dedfbf65be'
if(Test-Path -LiteralPath $dst){throw 'REFUSE_EXISTING_PATH'}
& git.exe clone --quiet --depth 1 --single-branch --no-tags --branch 'agent/qa-r67-portable-canary-regressions-20261014' 'https://github.com/foto6/boss.git' $dst
if($LASTEXITCODE -ne 0){throw 'QA_CLONE_FAILED'}
$h=([string](& git.exe -C $dst rev-parse HEAD)).Trim()
if($h -ne $sha){throw ('WRONG_HEAD '+$h)}
$log=Join-Path $dst 'QA_R67_NODE_RESULT.txt'
Push-Location -LiteralPath $dst
try{& node.exe --test tests/r65_autonomy_canary.test.cjs 2>&1|Out-File -LiteralPath $log -Encoding UTF8;$rc=$LASTEXITCODE}finally{Pop-Location}
Write-Output ('VERIFIED_SOURCE_SHA='+$h)
Write-Output ('NODE_EXIT='+$rc)
Select-String -LiteralPath $log -Pattern '^ℹ (?:tests|pass|fail|skipped)|^✖'|Select-Object -Last 15|ForEach-Object{Write-Output $_.Line}
Write-Output ('RESULT_LOG='+$log)
Write-Output ('PRODUCTION_BRIDGE_HEAD='+(& git.exe -C 'E:\WebAIBridge' rev-parse HEAD))
if($rc -ne 0){throw 'CORRECTED_QA_NODE_TEST_FAILED'}
